INSERT INTO scenic_spots (code, name, category, district, address, lon, lat, ticket, open_hours, description, image_url) VALUES
('CD001', '青城山-都江堰景区', '5A', '都江堰市', '都江堰市公园路', 103.610000, 31.002000, 80, '08:00-17:30', '世界文化遗产、国家5A级景区，由都江堰水利工程与青城山组成，被誉为“拜水都江堰，问道青城山”。', '/images/attractions/CD001.jpg'),
('CD002', '安仁古镇景区', '5A', '大邑县', '大邑县安仁镇金桂街', 103.616800, 30.510800, 0, '全天开放', '国家5A级景区，保存完好的民国公馆建筑群，拥有建川博物馆聚落，被称为“中国博物馆小镇”。', '/images/attractions/CD002.jpg'),
('CD003', '天台山景区', '5A', '邛崃市', '邛崃市天台山镇', 103.170600, 30.305800, 58, '08:00-18:00', '国家5A级景区，森林覆盖率高，以山奇、石怪、水美、林幽著称，是夏季避暑和观萤火虫的胜地。', '/images/attractions/CD003.jpg'),
('CD004', '三圣花乡景区', '4A', '锦江区', '锦江区三圣街道红砂村', 104.140400, 30.591900, 0, '全天开放', '国家4A级景区，由花乡农居、幸福梅林、江家菜地等组成，是成都近郊著名的花卉与乡村旅游区。', '/images/attractions/CD004.jpg'),
('CD005', '武侯祠博物馆', '4A', '武侯区', '武侯区武侯祠大街231号', 104.047200, 30.648800, 50, '08:00-18:00', '中国唯一君臣合祀祠庙，纪念刘备、诸葛亮等蜀汉英雄，与锦里古街相邻，是三国文化圣地。', '/images/attractions/CD005.jpg'),
('CD006', '杜甫草堂博物馆', '4A', '青羊区', '青羊区青华路37号', 104.026000, 30.661000, 50, '09:00-18:00', '唐代诗人杜甫流寓成都时的故居，是中国规模最大、保存最完好的杜甫纪念地，被誉为“中国文学圣地”。', '/images/attractions/CD006.jpg'),
('CD007', '成都大熊猫繁育研究基地', '4A', '成华区', '成华区熊猫大道1375号', 104.145000, 30.735500, 55, '07:30-18:00', '国家4A级景区，全球知名的大熊猫迁地保护与科研基地，可近距离观赏大熊猫、小熊猫等珍稀动物。', '/images/attractions/CD007.jpg'),
('CD008', '洛带古镇景区', '4A', '龙泉驿区', '龙泉驿区洛带镇', 104.320000, 30.642000, 0, '全天开放', '国家4A级景区，中国西部最大的客家聚居地，以客家土楼、广东会馆和客家美食闻名。', '/images/attractions/CD008.jpg'),
('CD009', '宝光桂湖文化旅游区', '4A', '新都区', '新都区宝光街81号', 104.157600, 30.833900, 20, '08:00-17:30', '国家4A级景区，由千年古刹宝光寺与明代状元杨升庵故居桂湖组成，文物与园林相得益彰。', '/images/attractions/CD009.jpg'),
('CD010', '黄龙溪古镇景区', '4A', '双流区', '双流区黄龙溪镇', 103.965600, 30.323600, 0, '全天开放', '国家4A级景区，拥有1700余年历史的水乡古镇，青石板街与溪流穿镇而过，是成都近郊热门古镇。', '/images/attractions/CD010.jpg'),
('CD011', '国色天乡一期', '4A', '温江区', '温江区万春镇天乡路', 103.824000, 30.721500, 150, '09:30-18:00', '国家4A级景区，大型主题乐园，由童话世界、水上乐园等园区组成，适合亲子游乐。', '/images/attractions/CD011.jpg'),
('CD012', '平乐古镇景区', '4A', '邛崃市', '邛崃市平乐镇', 103.334000, 30.348000, 0, '全天开放', '国家4A级景区，南方丝绸之路上的千年古镇，白沫江穿镇而过，以古桥、古树、古街著称。', '/images/attractions/CD012.jpg'),
('CD013', '金沙遗址博物馆', '4A', '青羊区', '青羊区金沙遗址路2号', 104.011500, 30.684000, 70, '09:00-18:00', '国家4A级景区，古蜀文明重要遗址，出土太阳神鸟金饰等珍贵文物，是了解成都城市史的窗口。', '/images/attractions/CD013.jpg'),
('CD014', '成都欢乐谷', '4A', '金牛区', '金牛区西华大道16号', 104.030500, 30.723000, 230, '09:30-21:00', '国家4A级景区，大型现代主题乐园，拥有多种大型游乐设备与演艺项目，是成都夜游热门目的地。', '/images/attractions/CD014.jpg'),
('CD015', '街子古镇景区', '4A', '崇州市', '崇州市街子镇', 103.557000, 30.814000, 0, '全天开放', '国家4A级景区，毗邻青城山，以明清建筑、味江河与千年银杏闻名，有“川西水乡”之称。', '/images/attractions/CD015.jpg'),
('CD016', '西岭雪山景区', '4A', '大邑县', '大邑县西岭镇', 103.192000, 30.700000, 30, '08:00-17:00', '国家4A级景区，成都第一高峰大雪塘所在地，因杜甫“窗含西岭千秋雪”诗句得名，是滑雪与观景胜地。', '/images/attractions/CD016.jpg'),
('CD017', '花水湾温泉度假区', '4A', '大邑县', '大邑县花水湾镇', 103.255400, 30.561300, 0, '全天开放', '国家4A级景区，以古海水温泉闻名，群山环抱、溪流潺潺，是成都周边知名温泉度假地。', '/images/attractions/CD017.jpg'),
('CD018', '花舞人间', '4A', '新津区', '新津区永商镇梨花大道', 103.795000, 30.391500, 60, '08:30-18:00', '国家4A级景区，大型花卉主题公园，四季花海与山水景观结合，是赏花休闲的热门去处。', '/images/attractions/CD018.jpg'),
('CD019', '成都海昌极地海洋世界', '4A', '天府新区', '天府新区天府大道南段2039号', 104.070500, 30.497500, 190, '09:00-17:30', '国家4A级景区，西南地区大型海洋主题公园，展示极地动物与海洋生物，拥有海豚表演等项目。', '/images/attractions/CD019.jpg'),
('CD020', '虹口风景区', '4A', '都江堰市', '都江堰市虹口乡', 103.665000, 31.118600, 0, '08:00-18:00', '国家4A级景区，以峡谷漂流和高山峡谷风光著称，森林茂密、溪流清澈，是夏季避暑漂流胜地。', '/images/attractions/CD020.jpg'),
('CD021', '桃花故里旅游景区', '4A', '龙泉驿区', '龙泉驿区山泉镇', 104.321700, 30.553800, 0, '全天开放', '国家4A级景区，成都国际桃花节主会场，春季漫山桃花盛开，是闻名全国的赏花目的地。', '/images/attractions/CD021.jpg'),
('CD022', '农科村景区', '4A', '郫都区', '郫都区友爱镇农科村', 103.794900, 30.820500, 0, '全天开放', '国家4A级景区，中国农家乐发源地，以盆景花木和乡村休闲旅游闻名，被誉为“鲜花盛开的村庄”。', '/images/attractions/CD022.jpg'),
('CD023', '成都新场古镇景区', '4A', '大邑县', '大邑县新场镇', 103.423800, 30.533800, 0, '全天开放', '国家4A级景区，保存完好的川西坝子古镇，古街、古巷、古桥众多，被称为“最后的川西坝子”。', '/images/attractions/CD023.jpg'),
('CD024', '非遗博览园', '4A', '青羊区', '青羊区光华大道二段601号', 103.920700, 30.676700, 0, '09:00-18:00', '国家4A级景区，国际非物质文化遗产节永久举办地，集中展示世界各地非遗项目与手工艺。', '/images/attractions/CD024.jpg'),
('CD025', '东郊记忆', '4A', '成华区', '成华区建设南支路4号', 104.126000, 30.671000, 0, '全天开放', '国家4A级景区，由老工业厂房改造的文创园区，集音乐、戏剧、展览与潮流商业于一体，是成都文化地标。', '/images/attractions/CD025.jpg'),
('CD026', '望丛祠', '4A', '郫都区', '郫都区望丛中路', 103.876000, 30.809800, 0, '08:30-17:30', '国家4A级景区，纪念古蜀国望帝杜宇、丛帝开明的祠庙，是蜀人寻根祭祖的重要场所。', '/images/attractions/CD026.jpg'),
('CD027', '三道堰景区', '4A', '郫都区', '郫都区永宁路南一段', 103.915900, 30.867900, 0, '全天开放', '国家4A级景区，因柏条河、徐堰河穿镇而过得名，水乡风貌优美，是成都近郊亲水休闲地。', '/images/attractions/CD027.jpg'),
('CD028', '五凤溪旅游景区', '4A', '金堂县', '金堂县五凤镇五凤溪社区', 104.477700, 30.607700, 0, '全天开放', '国家4A级景区，依山傍水的山地古镇，五条古街沿山脊延伸，是沱江流域重要的水运码头古镇。', '/images/attractions/CD028.jpg'),
('CD029', '宝山旅游区', '4A', '彭州市', '彭州市龙门山镇宝山村', 103.780900, 31.232500, 0, '全天开放', '国家4A级景区，龙门山中的生态旅游村，以温泉、峡谷与山地度假闻名，是全国乡村旅游重点村。', '/images/attractions/CD029.jpg'),
('CD030', '白鹿音乐小镇', '4A', '彭州市', '彭州市白鹿镇', 103.911000, 31.194000, 0, '全天开放', '国家4A级景区，以法式风情建筑和音乐文化活动闻名，法式教堂与欧式街区是热门打卡地。', '/images/attractions/CD030.jpg'),
('CD031', '石象湖景区', '4A', '蒲江县', '蒲江县朝阳湖镇', 103.421200, 30.188000, 70, '08:30-17:30', '国家4A级景区，以湖泊、森林与郁金香花海著称，生态环境优良，是成都西南的赏花度假地。', '/images/attractions/CD031.jpg'),
('CD032', '元通古镇景区', '4A', '崇州市', '崇州市元通镇', 103.622000, 30.733100, 0, '全天开放', '国家4A级景区，文井江畔的千年水乡古镇，古码头、吊脚楼与老街保存完好。', '/images/attractions/CD032.jpg'),
('CD033', '成都海滨城景区', '4A', '双流区', '双流区蛟龙港海滨城', 103.908300, 30.605800, 0, '10:00-22:00', '国家4A级景区，大型商业综合体景区，拥有室内海洋馆与丰富娱乐业态，是城南休闲消费地标。', '/images/attractions/CD033.jpg'),
('CD034', '锦门景区', '4A', '新都区', '新都区三河街道', 104.127900, 30.782200, 0, '全天开放', '国家4A级景区，以丝绸文化为主题的民国风情街区，是南丝绸之路起点的文化旅游地标。', '/images/attractions/CD034.jpg'),
('CD035', '灌县古城景区', '4A', '都江堰市', '都江堰市灌口街道', 103.621000, 30.998500, 0, '全天开放', '国家4A级景区，都江堰老城区改造而成的古城景区，紧邻都江堰水利工程，古街与城隍庙相映成趣。', '/images/attractions/CD035.jpg'),
('CD036', '浓园艺术博览园', '4A', '武侯区', '武侯区武侯大道三河段', 103.985000, 30.588500, 0, '09:00-18:00', '国家4A级景区，以艺术创作、展览与交流为核心的文化艺术园区，收藏展示大量书画与雕塑作品。', '/images/attractions/CD036.jpg'),
('CD037', '中国酒村·邛酒文化风情旅游村落', '4A', '邛崃市', '邛崃市卧龙镇', 103.469900, 30.372400, 0, '08:30-18:00', '国家4A级景区，以邛酒文化为主题，集酿酒体验、民俗展示与田园休闲于一体。', '/images/attractions/CD037.jpg'),
('CD038', '成佳茶乡景区', '4A', '蒲江县', '蒲江县成佳镇', 103.376700, 30.186800, 0, '全天开放', '国家4A级景区，以万亩茶园和茶文化体验闻名，可采茶制茶、品尝雀舌名茶。', '/images/attractions/CD038.jpg'),
('CD039', '幸福田园', '4A', '温江区', '温江区万春镇幸福村', 103.793900, 30.765700, 0, '全天开放', '国家4A级景区，川西林盘院落与田园景观结合的乡村旅游景区，展现天府农耕文化。', '/images/attractions/CD039.jpg'),
('CD040', '三道堰青杠树景区', '4A', '郫都区', '郫都区三道堰镇青杠树村', 103.960000, 30.841000, 0, '全天开放', '国家4A级景区，以川西民居和林盘水系为特色的田园综合体，是成都乡村振兴示范村。', '/images/attractions/CD040.jpg'),
('CD041', '斑竹林', '4A', '新津区', '新津区兴义镇', 103.810300, 30.492500, 0, '全天开放', '国家4A级景区，以成片竹林与田园湿地景观著称，生态环境清幽，是近郊休闲踏青地。', '/images/attractions/CD041.jpg'),
('CD042', '丹景山景区', '4A', '彭州市', '彭州市丹景山镇', 103.843200, 31.090000, 30, '08:00-18:00', '国家4A级景区，以牡丹花闻名，有“丹景山牡丹甲天下”之称，春季花会吸引大量游客。', '/images/attractions/CD042.jpg'),
('CD043', '天府花溪谷', '4A', '大邑县', '大邑县悦来镇', 103.427800, 30.715300, 60, '08:30-17:30', '国家4A级景区，山谷型花卉主题景区，四季花海与溪谷景观相融，兼具亲子游乐项目。', '/images/attractions/CD043.jpg'),
('CD044', '蔚然花海', '4A', '龙泉驿区', '龙泉驿区同安街道', 104.295500, 30.634800, 50, '09:00-18:00', '国家4A级景区，大型花卉观赏景区，以成片花海、灯光秀和露营活动吸引游客。', '/images/attractions/CD044.jpg'),
('CD045', '麓湖水城', '4A', '天府新区', '天府新区天府大道南一段', 104.065500, 30.458000, 0, '全天开放', '国家4A级景区，以人工湖群与生态社区构成的开放式水城，是成都城南生态休闲新地标。', '/images/attractions/CD045.jpg'),
('CD046', '战旗村景区', '4A', '郫都区', '郫都区唐昌镇战旗村', 103.792200, 30.941600, 0, '全天开放', '国家4A级景区，全国乡村振兴示范村，以川西民居、乡村十八坊和农耕文化体验闻名。', '/images/attractions/CD046.jpg'),
('CD047', '天府芙蓉园', '4A', '武侯区', '武侯区武侯新城', 103.983000, 30.594500, 0, '09:00-18:00', '国家4A级景区，以芙蓉花为主题的生态公园，展现成都“蓉城”文化，是城市休闲绿地。', '/images/attractions/CD047.jpg'),
('CD048', '天府国际慢城', '4A', '崇州市', '崇州市白头镇', 103.628600, 30.608500, 0, '全天开放', '国家4A级景区，以慢生活理念打造的田园度假区，拥有稻田景观、林盘院落与乡村民宿。', '/images/attractions/CD048.jpg'),
('CD049', '竹艺村', '4A', '崇州市', '崇州市道明镇', 103.589100, 30.652900, 0, '全天开放', '国家4A级景区，以国家级非遗道明竹编闻名，竹艺建筑“竹里”是网红打卡地。', '/images/attractions/CD049.jpg'),
('CD050', '青白江凤凰湖旅游景区', '4A', '青白江区', '青白江区凤凰湖大道', 104.280000, 30.899000, 0, '全天开放', '国家4A级景区，以樱花观赏和湖滨湿地景观著称，是成都北部重要的城市生态公园。', '/images/attractions/CD050.jpg'),
('CD051', '白鹤滩国家湿地公园', '4A', '新津区', '新津区白鹤滩', 103.805000, 30.390000, 0, '全天开放', '国家4A级景区，岷江畔的国家湿地公园，湿地生态与观鸟资源丰富，是自然科普与休闲胜地。', '/images/attractions/CD051.jpg'),
('CD052', '丹景台旅游景区', '4A', '东部新区', '东部新区龙泉山城市森林公园', 104.253000, 30.353400, 0, '09:00-17:00', '国家4A级景区，龙泉山城市森林公园核心观景点，可俯瞰三岔湖与成都东部城市景观。', '/images/attractions/CD052.jpg'),
('CD053', '成都川菜博物馆', '3A', '郫都区', '郫都区古城镇', 103.927900, 30.898000, 60, '09:00-18:00', '国家3A级景区，以川菜文化为主题的博物馆，可体验豆瓣制作、川菜烹饪与美食品鉴。', '/images/attractions/CD053.jpg'),
('CD054', '罨画池博物馆', '3A', '崇州市', '崇州市大东街', 103.672300, 30.629900, 8, '09:00-17:30', '国家3A级景区，四川保存最完好的古代园林之一，陆游祠与文庙同处一园，人文底蕴深厚。', '/images/attractions/CD054.jpg'),
('CD055', '邛崃市竹溪湖景区', '3A', '邛崃市', '邛崃市临邛镇小柏树水库', 103.398200, 30.445800, 20, '08:30-18:00', '国家3A级景区，以湖泊、竹林与丘陵景观为主，湖光山色清幽，是近郊垂钓休闲地。', '/images/attractions/CD055.jpg'),
('CD056', '铁像寺水街景区', '3A', '高新区', '高新区铁像寺路', 104.046500, 30.563000, 0, '全天开放', '国家3A级景区，融合川西水乡街巷与现代商业的开放式街区，是城南特色文化休闲地。', '/images/attractions/CD056.jpg'),
('CD057', '兴隆湖湿地公园', '3A', '天府新区', '天府新区兴隆街道', 104.077900, 30.396000, 0, '全天开放', '国家3A级景区，天府新区核心生态湖区，环湖绿道与湿地景观是现代公园城市展示窗口。', '/images/attractions/CD057.jpg'),
('CD058', '川西竹海景区', '3A', '邛崃市', '邛崃市平乐镇', 103.303000, 30.344500, 60, '08:30-17:30', '国家3A级景区，十万亩竹林连绵成海，有高空玻璃桥与溪谷步道，是避暑观景胜地。', '/images/attractions/CD058.jpg'),
('CD059', '宽窄巷子', '2A', '青羊区', '青羊区长顺上街', 104.055600, 30.665000, 0, '全天开放', '国家2A级景区，由宽巷子、窄巷子、井巷子组成的清代古街，是成都最具代表性的城市文化名片。', '/images/attractions/CD059.jpg'),
('CD060', '新津区纯阳观公园', '2A', '新津区', '新津区纯阳路', 103.794300, 30.423800, 0, '08:30-17:30', '国家2A级景区，以道教宫观纯阳观为核心的古建筑群，环境清幽，是川西著名道教文化场所。', '/images/attractions/CD060.jpg');
